/**
 * @name Command injection in subprocess calls
 * @description User-controlled data flowing to subprocess calls may allow command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to public functions
    source instanceof DataFlow::ParameterNode
    or
    // File reads
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      source = call.getAMethodCall("read")
    )
    or
    // Environment variables
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Subprocess calls with shell=True
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() and
      sink = call.getArg(_) and
      exists(DataFlow::Node shellArg |
        shellArg = call.getArgByName("shell") and
        shellArg.asExpr().(BooleanLiteral).booleanValue() = true
      )
    )
    or
    // os.system calls
    sink = API::moduleImport("os").getMember("system").getACall().getArg(0)
    or
    // os.popen calls
    sink = API::moduleImport("os").getMember("popen").getACall().getArg(0)
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection: user data from $@ flows to subprocess call", source.getNode(), "this source"

/**
 * @name Command injection in cffi source code
 * @description Detects command injection vulnerabilities in subprocess calls within cffi source
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-source-command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled sources: function parameters, file reads, environment variables
    source instanceof DataFlow::ParameterNode or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      source = call.getAMethodCall("read")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Subprocess calls that could execute commands
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() or
        call = API::moduleImport("os").getMember(["system", "popen", "popen2", "popen3", "popen4"]).getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where 
  CommandInjectionFlow::flowPath(source, sink) and
  // Filter to only source files (not testing)
  source.getNode().getLocation().getFile().getRelativePath().matches("src/%")
select sink.getNode(), source, sink, "Command injection: user data from $@ flows to subprocess call", source.getNode(), "this source"

/**
 * @name Code injection through C code generation
 * @description User-controlled data flows into C code generation without proper sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled sources: function parameters
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Calls to write() or similar methods that write C code
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["write", "writelines"] and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // String formatting operations that could inject code
      call = API::builtin("format").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;

import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where 
  CodeInjectionFlow::flowPath(source, sink) and
  // Focus on source files, not tests
  source.getNode().getLocation().getFile().getRelativePath().matches("src/cffi/%")
select sink.getNode(), source, sink, "Code injection: user data from $@ flows to C code generation", source.getNode(), "this source"

