/**
 * @name Unsafe deserialization
 * @description User-controlled data flows into deserialization functions
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-unsafe-deserialization
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module DeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled sources: function parameters, file reads
    source instanceof DataFlow::ParameterNode
    or
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["read", "readline", "readlines"] and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // pickle.loads, pickle.load
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // marshal.loads, marshal.load
      call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

